function closestHalves(nums: number[]): number {
  const m = nums.length, n = m / 2;
  const total = nums.reduce((s, x) => s + x, 0);
  let best = Infinity;
  for (let mask = 0; mask < 1 << m; mask++) {
    let cnt = 0, s = 0;
    for (let i = 0; i < m; i++) if (mask >> i & 1) { cnt++; s += nums[i]; }
    if (cnt === n) best = Math.min(best, Math.abs(total - 2 * s));
  }
  return best;
}

