function closestHalves(nums: number[]): number {
  const n = nums.length / 2;
  const total = nums.reduce((s, x) => s + x, 0);
  // sums[c] = every subset sum of 'half' that uses exactly c numbers
  const bySize = (half: number[]): number[][] => {
    const out: number[][] = Array.from({ length: n + 1 }, () => []);
    const sum = new Array(1 << n).fill(0), cnt = new Array(1 << n).fill(0);
    out[0].push(0);
    for (let mask = 1; mask < 1 << n; mask++) {
      const low = mask & -mask, i = 31 - Math.clz32(low);
      sum[mask] = sum[mask ^ low] + half[i];
      cnt[mask] = cnt[mask ^ low] + 1;
      out[cnt[mask]].push(sum[mask]);
    }
    return out;
  };
  const left = bySize(nums.slice(0, n)), right = bySize(nums.slice(n));
  for (const list of right) list.sort((a, b) => a - b);
  let best = Infinity;
  for (let c = 0; c <= n; c++) {
    const list = right[n - c];
    for (const a of left[c]) {
      let lo = 0, hi = list.length; // first b with 2(a + b) >= total
      while (lo < hi) { const mid = (lo + hi) >> 1; if (2 * (a + list[mid]) < total) lo = mid + 1; else hi = mid; }
      if (lo < list.length) best = Math.min(best, Math.abs(total - 2 * (a + list[lo])));
      if (lo > 0) best = Math.min(best, Math.abs(total - 2 * (a + list[lo - 1])));
      if (best === 0) return 0;
    }
  }
  return best;
}

