class Solution:
    def closestHalves(self, nums: List[int]) -> int:
        n, total = len(nums) // 2, sum(nums)

        def by_size(half):
            return [[sum(g) for g in itertools.combinations(half, c)] for c in range(n + 1)]

        left, right = by_size(nums[:n]), [sorted(l) for l in by_size(nums[n:])]
        best = math.inf
        for c in range(n + 1):
            lst = right[n - c]
            for a in left[c]:
                # first b with 2(a + b) >= total, i.e. b >= (total - 2a) / 2
                i = bisect.bisect_left(lst, (total - 2 * a + 1) // 2)
                for j in (i - 1, i):
                    if 0 <= j < len(lst):
                        best = min(best, abs(total - 2 * (a + lst[j])))
                if best == 0:
                    return 0
        return best

